using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the IChatClient through MEAI ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ---
var notepad = new Notepad();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        WebSearchTool.SearchAsync,
        nameof(WebSearchTool.SearchAsync),
        "Searches the web for the given query and returns a list of result snippets."),
    AIFunctionFactory.Create(
        notepad.SaveNote,
        nameof(notepad.SaveNote),
        "Saves a research note with a title and body. Use this to record key findings."),
    AIFunctionFactory.Create(
        notepad.GetNotes,
        nameof(notepad.GetNotes),
        "Returns all saved research notes so far."),
};

// --- Create the agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When the user provides a topic:
        1. Search the web 2-3 times with different queries to gather diverse information.
        2. Save key findings as notes using the note-taking tool.
        3. After gathering enough information, retrieve all your notes and produce a
           well-structured summary with sections and references.
        Be thorough but concise. Always cite which search results informed each point.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and summarizing findings.",
    tools: tools);

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

// --- Interactive loop ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       Research Agent (MAF + MEAI)    ║");
Console.WriteLine("║  Type a topic to research, or 'q'.  ║");
Console.WriteLine("╚══════════════════════════════════════╝");

while (true)
{
    Console.Write("\n> ");
    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("q", StringComparison.OrdinalIgnoreCase))
        break;

    notepad.Clear();
    Console.WriteLine("\nResearching...\n");

    try
    {
        AgentResponse response = await agent.RunAsync(
            $"Research the following topic and provide a summary: {input}",
            options: runOptions);

        Console.WriteLine("── Summary ──────────────────────────────");
        Console.WriteLine(response.Text);
        Console.WriteLine("──────────────────────────────────────────");

        if (response.Usage is { } usage)
        {
            Console.WriteLine(
                $"[Tokens — input: {usage.InputTokenCount}, output: {usage.OutputTokenCount}]");
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
    }
}

Console.WriteLine("Goodbye!");

// ── Tool implementations ────────────────────────────────────────────────

/// <summary>Web search tool that uses Bing search via HTML scraping as a fallback.</summary>
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" }
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    public static async Task<string> SearchAsync(
        [Description("The search query to look up on the web.")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await s_http.GetStringAsync(url);

            var snippets = ParseSnippets(html, maxResults: 5);
            if (snippets.Count == 0)
                return $"No results found for: {query}";

            return string.Join("\n\n", snippets.Select((s, i) => $"[{i + 1}] {s}"));
        }
        catch (Exception ex)
        {
            return $"Search failed ({ex.GetType().Name}): {ex.Message}";
        }
    }

    private static List<string> ParseSnippets(string html, int maxResults)
    {
        var results = new List<string>();

        // Parse DuckDuckGo HTML results — extract snippet text from result blocks
        var searchSpan = html.AsSpan();
        const string snippetClass = "result__snippet";
        const string titleClass = "result__a";

        int pos = 0;
        while (results.Count < maxResults)
        {
            int snippetIdx = html.IndexOf(snippetClass, pos, StringComparison.Ordinal);
            if (snippetIdx < 0) break;

            // Find the nearest preceding title
            int titleStart = html.LastIndexOf(titleClass, snippetIdx, StringComparison.Ordinal);
            string title = titleStart >= 0
                ? ExtractTagContent(html, titleStart)
                : "Untitled";

            string snippet = ExtractTagContent(html, snippetIdx);
            if (!string.IsNullOrWhiteSpace(snippet))
            {
                results.Add($"{title.Trim()}: {snippet.Trim()}");
            }

            pos = snippetIdx + snippetClass.Length;
        }

        return results;
    }

    private static string ExtractTagContent(string html, int classPos)
    {
        // Find the > that closes the tag containing this class
        int tagClose = html.IndexOf('>', classPos);
        if (tagClose < 0) return string.Empty;

        // Find the next closing tag
        int contentStart = tagClose + 1;
        int contentEnd = html.IndexOf('<', contentStart);
        if (contentEnd < 0) return string.Empty;

        var content = html[contentStart..contentEnd];
        // Strip any remaining HTML entities
        return System.Net.WebUtility.HtmlDecode(content).Trim();
    }
}

/// <summary>Simple in-memory notepad for the agent to record research findings.</summary>
sealed class Notepad
{
    private readonly List<(string Title, string Body)> _notes = [];

    public string SaveNote(
        [Description("Short title for the note.")] string title,
        [Description("The body/content of the note.")] string body)
    {
        _notes.Add((title, body));
        Console.WriteLine($"  📝 Note saved: \"{title}\"");
        return $"Note '{title}' saved (#{_notes.Count}).";
    }

    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Body}"));
    }

    public void Clear() => _notes.Clear();
}

